-- ============================================================
-- HR Workforce & Attrition Analytics Dashboard - Power BI Project
-- MySQL dataset: schema + sample data
-- ============================================================

DROP DATABASE IF EXISTS hr_analytics_db;
CREATE DATABASE hr_analytics_db CHARACTER SET utf8mb4;
USE hr_analytics_db;

SET FOREIGN_KEY_CHECKS = 0;

-- ---------------- DIM_DEPARTMENT ----------------
CREATE TABLE dim_department (
    department_id    INT PRIMARY KEY,
    department_name  VARCHAR(50) NOT NULL,
    location         VARCHAR(50) NOT NULL
) ENGINE=InnoDB;

-- ---------------- DIM_DATE ----------------
CREATE TABLE dim_date (
    date_id      INT PRIMARY KEY,
    full_date    DATE NOT NULL,
    month        TINYINT NOT NULL,
    month_name   VARCHAR(15) NOT NULL,
    quarter      TINYINT NOT NULL,
    year         SMALLINT NOT NULL
) ENGINE=InnoDB;

-- ---------------- FACT_ATTRITION (one row per employee) ----------------
CREATE TABLE fact_attrition (
    employee_id                 INT PRIMARY KEY,
    employee_name                VARCHAR(100) NOT NULL,
    gender                       VARCHAR(10) NOT NULL,
    age                          INT NOT NULL,
    marital_status               VARCHAR(15) NOT NULL,
    education                    VARCHAR(20) NOT NULL,
    department_id                INT NOT NULL,
    job_role                     VARCHAR(50) NOT NULL,
    hire_date_id                 INT NOT NULL,
    monthly_income               INT NOT NULL,
    business_travel              VARCHAR(20) NOT NULL,
    distance_from_home_km        INT NOT NULL,
    performance_rating           TINYINT NOT NULL,
    satisfaction_score           TINYINT NOT NULL,
    work_life_balance            TINYINT NOT NULL,
    overtime                     VARCHAR(5) NOT NULL,
    years_since_last_promotion   INT NOT NULL,
    num_companies_worked         INT NOT NULL,
    tenure_years                 DECIMAL(4,1) NOT NULL,
    attrition                    VARCHAR(5) NOT NULL,
    exit_date_id                 INT NULL,
    FOREIGN KEY (department_id) REFERENCES dim_department(department_id),
    FOREIGN KEY (hire_date_id) REFERENCES dim_date(date_id)
) ENGINE=InnoDB;

-- ============================================================
-- DATA
-- ============================================================

